import { FileSessionStore, z } from 'genkit/beta';
import { ai } from './ai.js';
import { createRefund } from './db.js';
import { lookupOrder } from './tools.js';

const store = new FileSessionStore('.genkit/sessions');

const issueRefund = ai.defineTool(
  {
    name: 'issueRefund',
    description: 'Refunds an amount to the customer for an order. Only call this after approveRefund returned approved.',
    inputSchema: z.object({ orderId: z.string(), amount: z.number() }),
    outputSchema: z.object({ refundId: z.string() }),
  },
  async ({ orderId, amount }) => {
    const refundId = createRefund(orderId, amount);
    ai.currentSession().addArtifacts([{ name: `receipt-${refundId}`, parts: [{ data: { refundId, orderId, amount } }] }]);
    return { refundId };
  },
);

const approveRefund = ai.defineInterrupt({
  name: 'approveRefund',
  description: 'Asks a human to approve a refund before it is issued.',
  inputSchema: z.object({ orderId: z.string(), amount: z.number(), reason: z.string() }),
  outputSchema: z.object({ approved: z.boolean(), note: z.string().optional() }),
});

/** Answers order status questions. */
export const orderAgent = ai.defineAgent({
  name: 'orderAgent',
  description: 'Answers questions about an order: its status, delivery date, tracking code and total.',
  system:
    'You are the Northwind Supplies order desk. Answer questions about orders using the lookupOrder tool. ' +
    'Quote the status, ETA and tracking code exactly as the tool returns them. If an order is not found, say so. ' +
    'When the customer does not name an order, use the order id from earlier in the conversation; ask for one only when the conversation has none.',
  tools: [lookupOrder],
  maxTurns: 4,
  store,
});

/** Handles refund requests and pauses for human approval before refunding. */
export const refundAgent = ai.defineAgent({
  name: 'refundAgent',
  description: 'Handles refund requests for an order. Refunds need human approval.',
  system:
    'Look up the order, then call approveRefund, then issueRefund only if approved. Never refund without approval. ' +
    'The refund amount is always the order total as lookupOrder returns it; never ask the customer for an amount.',
  tools: [lookupOrder, approveRefund, issueRefund],
  toolChoice: 'auto',
  maxTurns: 6,
  store,
});

const transferToOrderAgent = ai.defineTool(
  {
    name: 'transferToOrderAgent',
    description:
      'Hands an order question (status, delivery date, tracking code or total) to the order desk. ' +
      'Pass a self-contained request, including the order id when the customer has given one earlier in the conversation.',
    inputSchema: z.object({
      request: z.string().describe('What the customer wants to know, including the order id if it is known.'),
    }),
    outputSchema: z.string(),
  },
  async ({ request }) => {
    const response = await orderAgent.chat().send(request);
    return response.text;
  },
);

const transferToRefundAgent = ai.defineTool(
  {
    name: 'transferToRefundAgent',
    description:
      'Hands a refund request to the refund desk. Pass a self-contained request, including the order id when ' +
      'the customer has given one earlier in the conversation.',
    inputSchema: z.object({
      request: z.string().describe('What refund the customer wants, including the order id if it is known.'),
    }),
    outputSchema: z.string(),
  },
  async ({ request }) => {
    const response = await refundAgent.chat().send(request);
    return response.text;
  },
);

/** The front desk agent customers talk to first; routes to the order desk or refund desk instead of answering itself. */
export const triage = ai.defineAgent({
  name: 'triage',
  description: 'The Northwind Supplies front desk. Figures out what the customer needs and routes them to the right specialist.',
  system:
    'You are the Northwind Supplies front desk. You never answer order or refund questions yourself. ' +
    'Hand order questions (status, delivery date, tracking, total) to transferToOrderAgent, and refund requests to transferToRefundAgent. ' +
    'When you call either tool, pass a self-contained request that includes the order id whenever the customer mentioned one earlier in the conversation. ' +
    'Relay the specialist\'s answer back to the customer in your own reply.',
  tools: [transferToOrderAgent, transferToRefundAgent],
  maxTurns: 4,
  store,
});
